import time
from ute_common_admin.exception import AdminApiConnectionClosedException
from taf.sbts.oam.coam.admin import admin
from ta5g_global_var import ENB0_LMP_IP


DEFAULT_TIMEOUT = 300


def get_admin_interface(remote_host=None):
    if remote_host is None:
        return admin_interface()
    return remote_admin_interface(remote_host=remote_host)


class admin_interface(object):
    def __init__(self):
        self._taf_coam_admin_api = admin()

    def __enter__(self):
        self.__wait_until_admin_api_connection_established(timeout=DEFAULT_TIMEOUT)
        return self._taf_coam_admin_api

    def __exit__(self, exc_type, exc_value, traceback):
        self._taf_coam_admin_api.teardown()

    def __wait_until_admin_api_connection_established(self, timeout):
        connection_handler = None
        start_time = time.time()
        while time.time() - start_time < timeout and connection_handler is None:
            try:
                connection_handler = self.create_connection()
            except AdminApiConnectionClosedException:
                pass
        if connection_handler is None:
            raise ValueError("The connection has not been established in given time")

    def create_connection(self):
        return self._taf_coam_admin_api.connect_to(bts_host=ENB0_LMP_IP)


class remote_admin_interface(admin_interface):
    def __init__(self, remote_host):
        self._remote_host = remote_host
        super(remote_admin_interface, self).__init__()

    def create_connection(self):
        return self._taf_coam_admin_api.setup_admin(
            bts_host='192.168.255.129',
            remote_host=self._remote_host,
            remote_host_password='ute')
